HEAD = '<title>{title}</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700&family=Source+Serif+4:opsz,wght@8..60,400;8..60,600&family=IBM+Plex+Mono:wght@400;500;600&display=swap">\n\n<style>\n:root {\n  --bg:        #E7EAE7;\n  --surface:   #FAFBFA;\n  --surface-2: #F0F2EF;\n  --ink:       #171C1E;\n  --ink-soft:  #3D4749;\n  --muted:     #64716F;\n  --rule:      #C6CDC7;\n  --rule-soft: #DCE1DC;\n  --authored:  #7E5D10;\n  --authored-bg: #F2EAD6;\n  --emergent:  #2E7F8C;\n  --emergent-bg: #DCEBEC;\n  --refused:   #8A3B36;\n  --refused-bg: #F3E2E0;\n  --measure: 68ch;\n  --wide: 1120px;\n  --sans: Archivo, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;\n  --serif: "Source Serif 4", Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;\n  --mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"]) {\n    --bg:        #10161A;\n    --surface:   #182025;\n    --surface-2: #1E272C;\n    --ink:       #DDE4E5;\n    --ink-soft:  #B6C1C2;\n    --muted:     #85938F;\n    --rule:      #2E3A3F;\n    --rule-soft: #232D32;\n    --authored:  #D8A73F;\n    --authored-bg: #2A2314;\n    --emergent:  #62B6C1;\n    --emergent-bg: #14282C;\n    --refused:   #D9756C;\n    --refused-bg: #2C1917;\n  }\n}\n:root[data-theme="dark"] {\n  --bg:        #10161A;\n  --surface:   #182025;\n  --surface-2: #1E272C;\n  --ink:       #DDE4E5;\n  --ink-soft:  #B6C1C2;\n  --muted:     #85938F;\n  --rule:      #2E3A3F;\n  --rule-soft: #232D32;\n  --authored:  #D8A73F;\n  --authored-bg: #2A2314;\n  --emergent:  #62B6C1;\n  --emergent-bg: #14282C;\n  --refused:   #D9756C;\n  --refused-bg: #2C1917;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  background: var(--bg);\n  color: var(--ink);\n  font-family: var(--serif);\n  font-size: 17px;\n  line-height: 1.62;\n  margin: 0;\n  padding: 0 24px 110px;\n  -webkit-font-smoothing: antialiased;\n}\n\n.page { max-width: var(--wide); margin: 0 auto; }\n.col  { max-width: var(--measure); }\n\nh1, h2, h3, .eyebrow, .lbl, th, .chip, .num, .actno, figcaption, .cap {\n  font-family: var(--sans);\n}\ncode, pre, .mono { font-family: var(--mono); }\n\n/* ---- masthead ---- */\n.masthead { padding: 68px 0 36px; border-bottom: 2px solid var(--ink); margin-bottom: 34px; }\n.eyebrow {\n  font-size: 11px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase;\n  color: var(--muted); margin: 0 0 18px;\n}\nh1 {\n  font-size: clamp(36px, 5.8vw, 62px); font-weight: 700; letter-spacing: -0.028em;\n  line-height: 1.03; margin: 0 0 20px; text-wrap: balance; max-width: 17ch;\n}\n.standfirst { font-size: 20px; line-height: 1.5; color: var(--ink-soft); max-width: 62ch; margin: 0; }\n\n/* ---- caveat ---- */\n.caveat {\n  border: 1px solid var(--rule); border-left: 3px solid var(--refused);\n  background: var(--surface); padding: 18px 22px; margin: 0 0 40px;\n  font-size: 15px; line-height: 1.55;\n}\n.caveat p { margin: 0 0 10px; }\n.caveat p:last-child { margin-bottom: 0; }\n.caveat .lbl {\n  display: block; font-size: 11px; font-weight: 600; letter-spacing: .13em;\n  text-transform: uppercase; color: var(--muted); margin-bottom: 8px;\n}\n\n/* ---- stat strip ---- */\n.stats { display: grid; gap: 1px; background: var(--rule); border: 1px solid var(--rule); margin: 0 0 56px; }\n@media (min-width: 660px) { .stats { grid-template-columns: repeat(2, 1fr); } }\n@media (min-width: 980px) { .stats { grid-template-columns: repeat(4, 1fr); } }\n.stat { background: var(--surface); padding: 20px 18px; }\n.stat .num {\n  display: block; font-size: 36px; font-weight: 700; letter-spacing: -0.03em;\n  line-height: 1; font-variant-numeric: tabular-nums; color: var(--ink);\n}\n.stat .cap { display: block; font-size: 12.5px; line-height: 1.4; color: var(--muted); margin-top: 9px; }\n\n/* ---- acts ---- */\nsection { margin: 0 0 72px; }\n.acthead { display: flex; align-items: baseline; gap: 14px; border-bottom: 1px solid var(--rule); padding-bottom: 10px; margin-bottom: 22px; }\n.actno {\n  font-size: 12px; font-weight: 700; letter-spacing: .14em; color: var(--emergent);\n  font-variant-numeric: tabular-nums;\n}\nh2 {\n  font-size: 12px; font-weight: 600; letter-spacing: .15em; text-transform: uppercase;\n  color: var(--muted); margin: 0;\n}\n.h2sub {\n  font-family: var(--sans); font-size: clamp(23px, 3.1vw, 31px); font-weight: 600;\n  letter-spacing: -0.02em; line-height: 1.18; margin: 0 0 22px; text-wrap: balance; max-width: 28ch;\n}\nh3 { font-size: 17px; font-weight: 600; letter-spacing: -0.01em; margin: 32px 0 10px; font-family: var(--sans); }\np { margin: 0 0 18px; }\nstrong { font-weight: 600; }\nem { font-style: italic; }\na { color: var(--emergent); text-decoration-thickness: 1px; text-underline-offset: 2px; }\na:focus-visible { outline: 2px solid var(--emergent); outline-offset: 3px; }\n\n/* ---- risk quarters ---- */\n.quarters { display: grid; gap: 1px; background: var(--rule); border: 1px solid var(--rule); margin: 0 0 28px; }\n@media (min-width: 700px) { .quarters { grid-template-columns: repeat(2, 1fr); } }\n@media (min-width: 1000px) { .quarters { grid-template-columns: repeat(4, 1fr); } }\n.quarter { background: var(--surface); padding: 20px 20px; }\n.quarter .qv { display: block; font-family: var(--sans); font-size: 13px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--emergent); margin-bottom: 10px; }\n.quarter .qt { font-family: var(--sans); font-size: 16px; font-weight: 600; line-height: 1.3; margin: 0 0 8px; }\n.quarter p { font-size: 14px; line-height: 1.5; color: var(--ink-soft); margin: 0; }\n\n/* ---- order timeline ---- */\n.orders { border: 1px solid var(--rule); background: var(--surface); margin: 28px 0; }\n.orderrow { display: grid; grid-template-columns: 84px 1fr; border-bottom: 1px solid var(--rule-soft); }\n.orderrow:last-child { border-bottom: 0; }\n.orderrow.final { background: var(--emergent-bg); }\n.ordertag {\n  font-family: var(--mono); font-size: 11px; font-weight: 600; color: var(--muted);\n  padding: 18px 0 18px 16px; letter-spacing: .04em;\n}\n.orderrow.final .ordertag { color: var(--emergent); }\n.orderbody { padding: 18px 20px 18px 4px; }\n.orderseq {\n  font-family: var(--mono); font-size: 15px; font-weight: 600; letter-spacing: .06em;\n  margin: 0 0 7px; color: var(--ink);\n}\n.orderseq .strike { text-decoration: line-through; opacity: .5; }\n.orderwhy { font-size: 14.5px; line-height: 1.5; color: var(--ink-soft); margin: 0; }\n\n/* ---- findings ---- */\n.finds { display: grid; gap: 1px; background: var(--rule); border: 1px solid var(--rule); margin: 26px 0; }\n@media (min-width: 780px) { .finds { grid-template-columns: 1fr 1fr; } }\n.find { background: var(--surface); padding: 20px 22px; }\n.find .fid {\n  font-family: var(--mono); font-size: 11.5px; font-weight: 600; letter-spacing: .05em;\n  color: var(--authored); display: block; margin-bottom: 8px;\n}\n.find.bad .fid { color: var(--refused); }\n.find .ftitle { font-family: var(--sans); font-size: 15.5px; font-weight: 600; line-height: 1.35; margin: 0 0 8px; }\n.find p { font-size: 14.5px; line-height: 1.52; margin: 0; color: var(--ink-soft); }\n\n/* ---- chips ---- */\n.chip {\n  display: inline-block; font-size: 10.5px; font-weight: 600; letter-spacing: .09em;\n  text-transform: uppercase; padding: 3px 8px; border-radius: 2px; white-space: nowrap;\n}\n.chip-a { background: var(--authored-bg); color: var(--authored); }\n.chip-e { background: var(--emergent-bg); color: var(--emergent); }\n.chip-x { background: var(--refused-bg); color: var(--refused); }\n.chip-n { background: var(--surface-2); color: var(--muted); border: 1px solid var(--rule); }\n\n/* ---- figures ---- */\nfigure { margin: 32px 0; }\nfigure svg { display: block; width: 100%; max-width: 100%; height: auto; color: var(--ink); }\n.figwrap { background: var(--surface); border: 1px solid var(--rule); padding: 24px 20px 16px; overflow-x: auto; }\nfigcaption { font-size: 13.5px; line-height: 1.5; color: var(--muted); margin-top: 16px; max-width: 82ch; }\nfigcaption b { color: var(--ink-soft); font-weight: 600; }\n.figwrap svg .s-bad  { stroke: var(--refused); }\n.figwrap svg .s-good { stroke: var(--emergent); }\n.figwrap svg .s-warn { stroke: var(--authored); }\n.figwrap svg .t-bad  { fill: var(--refused); }\n.figwrap svg .t-good { fill: var(--emergent); }\n.figwrap svg .t-warn { fill: var(--authored); }\n\n/* ---- tables ---- */\n.tablewrap { overflow-x: auto; border: 1px solid var(--rule); background: var(--surface); margin: 26px 0; }\ntable { border-collapse: collapse; width: 100%; font-size: 15px; }\nth {\n  text-align: left; font-size: 11px; font-weight: 600; letter-spacing: .11em; text-transform: uppercase;\n  color: var(--muted); padding: 13px 16px; border-bottom: 1px solid var(--rule); white-space: nowrap;\n}\ntd { padding: 13px 16px; border-bottom: 1px solid var(--rule-soft); vertical-align: top; line-height: 1.45; }\ntr:last-child td { border-bottom: 0; }\ntd.mono { font-family: var(--mono); font-size: 13px; }\n.tabnum { font-variant-numeric: tabular-nums; }\ntd.good { color: var(--emergent); font-weight: 600; }\ntd.bad  { color: var(--refused); font-weight: 600; }\n\n/* ---- callout ---- */\n.note {\n  border-left: 3px solid var(--authored); background: var(--surface); padding: 18px 22px;\n  margin: 26px 0; font-size: 16px;\n}\n.note.teal { border-left-color: var(--emergent); }\n.note.red  { border-left-color: var(--refused); }\n.note p:last-child { margin-bottom: 0; }\n.note .lbl {\n  display: block; font-family: var(--sans); font-size: 11px; font-weight: 600; letter-spacing: .13em;\n  text-transform: uppercase; color: var(--muted); margin-bottom: 7px;\n}\n\ncode { font-size: .87em; background: var(--surface-2); padding: 1px 5px; border: 1px solid var(--rule-soft); }\n\nul.tight { margin: 0 0 18px; padding-left: 22px; }\nul.tight li { margin-bottom: 11px; }\n\n/* ---- open items ---- */\n.opens { border: 1px solid var(--rule); background: var(--surface); margin: 26px 0; }\n.open { display: grid; grid-template-columns: auto 1fr; gap: 16px; padding: 18px 22px; border-bottom: 1px solid var(--rule-soft); align-items: start; }\n.open:last-child { border-bottom: 0; }\n.open .otag { font-family: var(--mono); font-size: 11.5px; font-weight: 600; color: var(--muted); padding-top: 3px; white-space: nowrap; }\n.open .otitle { font-family: var(--sans); font-size: 15.5px; font-weight: 600; line-height: 1.35; margin: 0 0 6px; }\n.open p { font-size: 14.5px; line-height: 1.5; margin: 0; color: var(--ink-soft); }\n\nhr.end { border: 0; border-top: 2px solid var(--ink); margin: 56px 0 0; }\n.colophon { font-family: var(--sans); font-size: 13px; line-height: 1.6; color: var(--muted); padding-top: 18px; max-width: 80ch; }\n\n/* ---- task rail ---- */\n.rail { border: 1px solid var(--rule); background: var(--surface); margin: 28px 0; }\n.railrow { display: grid; grid-template-columns: 52px 1fr; gap: 0; border-bottom: 1px solid var(--rule-soft); }\n.railrow:last-child { border-bottom: 0; }\n.railno {\n  font-family: var(--mono); font-size: 13px; font-weight: 600; color: var(--muted);\n  padding: 16px 0 16px 16px; font-variant-numeric: tabular-nums;\n}\n.railbody { padding: 16px 18px 16px 6px; }\n.railtitle { font-family: var(--sans); font-size: 15.5px; font-weight: 600; line-height: 1.35; margin: 0 0 5px; }\n.railnote { font-size: 14.5px; line-height: 1.5; color: var(--ink-soft); margin: 0; }\n.railrow.merged { background: var(--surface-2); }\n.railrow.merged .railtitle { color: var(--muted); font-weight: 500; }\n.railmeta { font-family: var(--mono); font-size: 11.5px; color: var(--muted); margin-top: 7px; display: block; }\n\n/* ---- risk pair ---- */\n.riskpair { display: grid; gap: 1px; background: var(--rule); border: 1px solid var(--rule); margin: 0 0 28px; }\n@media (min-width: 820px) { .riskpair { grid-template-columns: 1fr 1fr; } }\n.riskcell { background: var(--surface); padding: 22px 24px; }\n.riskcell .lbl {\n  display: block; font-family: var(--sans); font-size: 11px; font-weight: 600; letter-spacing: .13em;\n  text-transform: uppercase; color: var(--muted); margin-bottom: 10px;\n}\n.riskcell .claim { font-size: 18px; line-height: 1.45; margin: 0 0 12px; }\n.riskcell .foot { font-size: 14px; line-height: 1.5; color: var(--ink-soft); margin: 0; }\n.riskcell.moved .claim { color: var(--muted); }\n\n/* ---- milestone strip: which rows this page covers ---- */\n.covers { display: grid; gap: 1px; background: var(--rule); border: 1px solid var(--rule); margin: 0 0 40px; }\n@media (min-width: 700px) { .covers { grid-template-columns: repeat(3, 1fr); } }\n@media (min-width: 1000px) { .covers { grid-template-columns: repeat(6, 1fr); } }\n.cover { background: var(--surface); padding: 16px 16px; }\n.cover .cno {\n  display: block; font-family: var(--mono); font-size: 19px; font-weight: 600;\n  color: var(--emergent); letter-spacing: -0.01em; margin-bottom: 6px;\n}\n.cover .cnm { font-family: var(--sans); font-size: 13px; line-height: 1.35; color: var(--ink-soft); }\n</style>\n\n<div class="page">\n'
FOOT = '\n</div>\n'
import sys
def build(out, title, body):
    open(out,'w').write(HEAD.replace('{title}', title) + body + FOOT)
